insert into public.begleiter_saetze (key, flaeche, kontext, welt, register, varianten, platzhalter, notiz) values
 ('heft.empfang.erster',      'heft','hero',  null,'buehne', '{"de":["Ich bin PAWN. Stöber in Ruhe — oder tipp mich an, dann zeige ich dir den Weg.","Willkommen. Drei Welten liegen vor dir. Ich bleibe in der Nähe."],"en":["I am PAWN. Browse in peace — or tap me and I will show you around.","Welcome. Three worlds ahead of you. I will stay close."]}', '{}', 'Erster Besuch, einmal'),
 ('heft.empfang.wieder',      'heft','hero',  null,'buehne', '{"de":["Willkommen zurück.","Schön, dass du wieder da bist."],"en":["Welcome back.","Good to see you again."]}', '{}', 'Wiederkehr ohne Merkliste'),
 ('heft.empfang.wieder_merk', 'heft','hero',  null,'buehne', '{"de":["Willkommen zurück. {werk} von {haus} ist noch da."],"en":["Welcome back. {werk} by {haus} is still here."]}', '{werk,haus}', 'Nur wenn das gemerkte Stück noch veröffentlicht ist'),
 ('heft.stillstand.hero',     'heft','hero',  null,'buehne', '{"de":["Mode, Interior, Kunst — welche zuerst?"],"en":["Fashion, interior, art — which first?"]}', '{}', 'Mit drei Chips'),
 ('heft.stillstand.stage',    'heft','stage', null,'buehne', '{"de":["Tipp ein Plus an — jedes Stück hat eine Geschichte."],"en":["Tap a plus — every piece has a story."]}', '{}', null),
 ('heft.welt.gewaehlt',       'heft','stage', null,'buehne', '{"de":["{welt}. Ich stelle dir hier immer wieder Neues auf."],"en":["{welt}. I will keep putting new pieces on this stage for you."]}', '{welt}', null),
 ('heft.verweilen.werk',      'heft','werk',  null,'buehne', '{"de":["{werk}: {material}, von {haus} aus {ort}."],"en":["{werk}: {material}, by {haus} from {ort}."]}', '{werk,material,haus,ort}', 'Nur mit allen vier Feldern'),
 ('heft.verweilen.bestellung','heft','werk',  null,'buehne', '{"de":["{werk} entsteht auf Bestellung — etwa {lead} Tage, dann ist es bei dir."],"en":["{werk} is made to order — about {lead} days, then it is yours."]}', '{werk,lead}', 'inventory_mode made_to_order + lead_time_days'),
 ('heft.merken.erstes',       'heft','werk',  null,'buehne', '{"de":["Gemerkt. Ein Stück sagt wenig — merk dir ein zweites, dann lese ich."],"en":["Noted. One piece says little — save a second and I will read."]}', '{}', null),
 ('heft.merken.zweites',      'heft','werk',  null,'buehne', '{"de":["Zwei Stücke. Soll ich lesen, was die beiden gemeinsam haben?"],"en":["Two pieces. Shall I read what they have in common?"]}', '{}', 'Angebot: Befund'),
 ('heft.merken.drittes',      'heft','werk',  null,'buehne', '{"de":["Drei gemerkt. Deine Linie wird deutlich — willst du sie sehen?"],"en":["Three saved. Your line is getting clear — want to see it?"]}', '{}', 'Führt zur DNA'),
 ('heft.haus.betreten',       'heft','haus',  null,'buehne', '{"de":["Das ist {haus}, Haus {nummer}. Zwei Seiten weiter steht das Atelier."],"en":["This is {haus}, house {nummer}. Two pages on, the atelier."]}', '{haus,nummer}', null),
 ('heft.quiz.fertig',         'heft','dna',   null,'buehne', '{"de":["Ich habe deine Linie. Ich glaube, ich kenne deinen Typ — sieh nach, ob ich recht habe."],"en":["I have your line. I think I know your type — see if I am right."]}', '{}', 'Führt zur Archetyp-Seite'),
 ('heft.archetyp.bestaetigt', 'heft','dna',   null,'buehne', '{"de":["Gut. Dann weiß ich, was ich dir aufstelle."],"en":["Good. Then I know what to put on stage for you."]}', '{}', null),
 ('heft.anprobe.angebot',     'heft','werk',  'mode','buehne', '{"de":["Willst du {werk} an dir sehen?"],"en":["Want to see {werk} on you?"]}', '{werk}', 'Nur mit aktivem Avatar'),
 ('heft.anprobe.ohne_avatar', 'heft','werk',  'mode','buehne', '{"de":["Ich kann dir zeigen, wie {werk} an dir aussieht. Dafür brauche ich einmal ein Foto von dir."],"en":["I can show you how {werk} looks on you. I need one photo of you for that."]}', '{werk}', 'Konto, kein Avatar — einmal überhaupt'),
 ('heft.anprobe.gast',        'heft','werk',  'mode','buehne', '{"de":["Mit einem Konto zeige ich dir {werk} an dir. Ein Foto, einmal."],"en":["With an account I can show you {werk} on you. One photo, once."]}', '{werk}', 'Gast — einmal je Sitzung'),
 ('heft.raum.angebot',        'heft','werk',  'interior','buehne', '{"de":["Willst du {werk} in deinem Raum sehen?"],"en":["Want to see {werk} in your room?"]}', '{werk}', null),
 ('heft.wand.angebot',        'heft','werk',  'kunst','buehne', '{"de":["Soll ich {werk} an deine Wand hängen? Ein Foto der Wand genügt."],"en":["Shall I hang {werk} on your wall? A photo of the wall is enough."]}', '{werk}', null),
 ('heft.anprobe.fertig',      'heft','werk',  null,'buehne', '{"de":["So sieht es aus. Passt es?"],"en":["This is how it looks. Does it fit?"]}', '{}', 'Chips: Passt / Eher nicht'),
 ('heft.suche.leer',          'heft','lesen', null,'buehne', '{"de":["Dazu habe ich nichts. Sag mir, was du suchst — anders."],"en":["Nothing for that. Tell me what you are looking for — differently."]}', '{}', 'Öffnet das Gespräch'),
 ('heft.hilfe',               'heft','lesen', null,'buehne', '{"de":["Suchst du etwas Bestimmtes? Sag es mir."],"en":["Looking for something specific? Tell me."]}', '{}', null),
 ('heft.kasse',               'heft','kasse', null,'buehne', '{"de":["Alles da? Ich bleibe, bis es durch ist."],"en":["All set? I will stay until it is through."]}', '{}', null),
 ('heft.kauf',                'heft','kasse', null,'buehne', '{"de":["Danke. {haus} erfährt es jetzt."],"en":["Thank you. {haus} hears about it now."]}', '{haus}', null),
 ('heft.rang.aufstieg',       'heft','dna',   null,'buehne', '{"de":["Ich weiß jetzt mehr über dich. Sieh mich an."],"en":["I know more about you now. Look at me."]}', '{}', 'Die Figur wechselt'),
 ('studio.vorschau.neu',      'studio','hub', null,'betrieb', '{"de":["Deine Doppelseite hat jetzt eine echte Vorschau — genau so, wie das Heft sie zeigt."],"en":["Your spread now has a real preview — exactly as the magazine shows it."]}', '{}', 'Einmal überhaupt'),
 ('studio.buehne.unter_drei', 'studio','heft',null,'betrieb', '{"de":["Auf deiner Bühne stehen {n} Werke. Ab drei kann ich sie veröffentlichen."],"en":["{n} works on your stage. From three on, I can publish it."]}', '{n}', null),
 ('studio.freistellen.angebot','studio','werk',null,'betrieb','{"de":["{werk} hat noch keinen Freisteller. Soll ich ihn machen? Ein Credit."],"en":["{werk} has no cut-out yet. Shall I make one? One credit."]}', '{werk}', null),
 ('studio.aufrufe',           'studio','hub', null,'betrieb', '{"de":["{n} Aufrufe für {werk} seit gestern."],"en":["{n} views for {werk} since yesterday."]}', '{n,werk}', 'Nur aus page_visits, nie geschätzt'),
 ('studio.anfrage.neu',       'studio','hub', null,'betrieb', '{"de":["Eine Anfrage zu {werk}. Sie wartet im Postfach."],"en":["An inquiry about {werk}. It is waiting in your inbox."]}', '{werk}', null)
